// FIXED: Layout is now Featured → Categories → Items (no duplicate grid)
app.get("/store", async (req, res) => {
  const query = db.createQuery("storeItems").order("createdAt", { descending: true });
  const [items] = await db.runQuery(query);

  // Featured (random daily from available items)
  let featuredItems = [];
  const availableItems = items.filter(item => item.soldOut !== true);
  if (availableItems.length >= 3) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const seed = today.getTime();
    const shuffled = [...availableItems];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor((seed + i) % (i + 1) * (i + 1) / 1000) % (i + 1);
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    featuredItems = shuffled.slice(0, 3);
  }

  let featuredHtml = "";
  if (featuredItems.length > 0) {
    featuredHtml = `
      <section id="featured" style="padding: 5rem 5% 3rem; position: relative; z-index: 2;">
        <h2 style="text-align:center; font-size:3.2rem; color:#00ff50; margin-bottom:2.5rem; text-shadow:0 0 25px #00ff50;">Featured Drop</h2>
        <div class="featured-carousel">
          <div class="carousel-track">
            ${featuredItems.map(item => {
              const entityKey = item[Datastore.KEY];
              const itemId = entityKey.id || entityKey.name;
              const firstImage = item.imageUrls?.[0] || item.imageUrl || 'https://via.placeholder.com/600?text=Featured';
              return `
                <div class="carousel-slide">
                  <div class="featured-card" style="border:1px solid rgba(0,255,80,0.25); background:rgba(10,10,10,0.75); border-radius:20px; overflow:hidden; backdrop-filter:blur(10px); box-shadow:0 10px 40px rgba(0,0,0,0.6); position:relative;">
                    <a href="/product/${itemId}" style="text-decoration:none; color:inherit; display:block;">
                      <div style="height:560px; overflow:hidden;">
                        <img src="${firstImage}" alt="${item.description}" style="width:100%; height:100%; object-fit:cover; transition:transform 0.6s ease;">
                      </div>
                      <div style="padding:1.8rem; text-align:center;">
                        <h3 style="color:#00ff50; font-size:1.9rem; margin-bottom:0.7rem;">${item.description}</h3>
                        <div style="font-size:1.8rem; font-weight:900; color:#d0ffd0;">${formatNaira(item.price)}</div>
                      </div>
                    </a>
                    <button class="add-to-cart-small"
                            onclick="addToCart('${itemId}', '${item.description.replace(/'/g, "\\'")}', ${item.price}, '${firstImage}')">
                      ADD TO CART
                    </button>
                    <div style="position:absolute; top:15px; left:15px; background:rgba(0,255,80,0.3); color:#00ff50; padding:0.5rem 1.1rem; border-radius:50px; font-size:1rem; font-weight:600; backdrop-filter:blur(6px);">FEATURED</div>
                  </div>
                </div>
              `;
            }).join('')}
          </div>
          <button class="carousel-prev">←</button>
          <button class="carousel-next">→</button>
          <div class="carousel-dots">
            ${featuredItems.map((_, i) => `<span class="carousel-dot ${i === 0 ? 'active' : ''}" data-index="${i}"></span>`).join('')}
          </div>
        </div>
      </section>
    `;
  }

  // Regular items grid (with data-category for JS filtering)
  let itemsHtml = "";
  items.forEach(item => {
    const entityKey = item[Datastore.KEY];
    const itemId = entityKey.id || entityKey.name;
    const firstImage = item.imageUrls?.[0] || item.imageUrl || 'https://via.placeholder.com/400?text=No+Image';
    const isSoldOut = item.soldOut === true;
    const cat = item.category || "uncategorized";

    itemsHtml += `
      <div class="card ${isSoldOut ? 'sold-out-card' : ''}" data-category="${cat}" style="position:relative;">
        <a href="/product/${itemId}" class="card-link">
          <img src="${firstImage}" alt="${item.description}">
          ${isSoldOut ? `<div class="sold-out-overlay"><div class="sold-out-text">SOLD OUT</div></div>` : ''}
        </a>
        <div class="card-info">
          <h3>${item.description}</h3>
          <div class="price">${formatNaira(item.price)}</div>
          ${item.category ? `<small style="opacity:0.6;">${item.category}</small>` : ''}
        </div>
        ${!isSoldOut ? `
          <button class="add-to-cart-small"
                  onclick="addToCart('${itemId}', '${item.description.replace(/'/g, "\\'")}', ${item.price}, '${firstImage}')">
            ADD TO CART
          </button>
        ` : ''}
      </div>
    `;
  });

  res.send(`
<!DOCTYPE html>
<html lang="en">
<head>
  <title>LENG Store</title>
  ${sharedHead}
  <style>
    #store-hero {
      height: 18vh;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      text-align: center;
      padding: 0 5%;
      position: relative;
      z-index: 2;
    }
    #store-hero h1 {
      font-size: clamp(4rem, 10vw, 8rem);
      color: #00ff50;
      text-shadow: 0 0 40px rgba(0,255,80,0.6);
    }
    #store-hero p {
      font-size: 1.3rem;
      opacity: 0.7;
      margin-top: 0.5rem;
    }
    #products {
      padding: 4rem 5% 8rem;
      position: relative;
      z-index: 2;
    }

    /* Sold Out Styles */
    .sold-out-card {
      opacity: 0.5;
      border-color: #ff0044 !important;
    }
    .sold-out-card:hover {
      transform: translateY(-8px) scale(1.02) !important;
    }
    .sold-out-overlay {
      position: absolute;
      top: 0; left: 0;
      width: 100%; height: 100%;
      background: rgba(0, 255, 80, 0.75);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 5;
      backdrop-filter: blur(4px);
    }
    .sold-out-text {
      color: white;
      font-size: 2.8rem;
      font-weight: 900;
      text-transform: uppercase;
      letter-spacing: 6px;
      text-shadow: 0 0 30px rgba(0,0,0,0.9);
      border: 4px solid white;
      padding: 12px 40px;
      border-radius: 8px;
      transform: rotate(-12deg);
      animation: pulse-sold 2s infinite;
    }
    @keyframes pulse-sold {
      0%, 100% { transform: rotate(-12deg) scale(1); }
      50% { transform: rotate(-12deg) scale(1.08); }
    }

    /* Carousel Styles */
    .featured-carousel {
      position: relative;
      max-width: 1400px;
      margin: 0 auto;
      overflow: hidden;
    }
    .carousel-track {
      display: flex;
      transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
    }
    .carousel-slide {
      flex: 0 0 100%;
      min-width: 100%;
      padding: 0 1.5rem;
      box-sizing: border-box;
    }
    .carousel-prev, .carousel-next {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      background: rgba(0,255,80,0.15);
      color: #00ff50;
      border: 1px solid rgba(0,255,80,0.4);
      font-size: 2.2rem;
      width: 60px; height: 60px;
      border-radius: 50%;
      cursor: pointer;
      z-index: 10;
      backdrop-filter: blur(6px);
      transition: all 0.3s;
    }
    .carousel-prev:hover, .carousel-next:hover {
      background: #00ff50;
      color: #000;
      box-shadow: 0 0 30px rgba(0,255,80,0.6);
      transform: translateY(-50%) scale(1.12);
    }
    .carousel-prev { left: 20px; }
    .carousel-next { right: 20px; }
    .carousel-dots {
      text-align: center;
      padding: 1.8rem 0 0.5rem;
    }
    .carousel-dot {
      height: 13px; width: 13px;
      margin: 0 9px;
      background: rgba(0,255,80,0.3);
      border-radius: 50%;
      display: inline-block;
      cursor: pointer;
      transition: all 0.3s;
    }
    .carousel-dot.active {
      background: #00ff50;
      transform: scale(1.4);
    }

    /* Category Styles */
    #categories {
      padding: 2rem 5% 3rem;
      position: relative;
      z-index: 2;
    }
    .category-box {
      cursor: pointer;
      background: rgba(10,10,10,0.85);
      border: 1px solid rgba(0,255,80,0.3);
      border-radius: 16px;
      padding: 1.5rem 2rem;
      min-width: 160px;
      text-align: center;
      transition: all 0.4s;
    }
    .category-box:hover,
    .category-box.active {
      border-color: #00ff50;
      background: rgba(0,255,80,0.08);
      transform: translateY(-4px);
      box-shadow: 0 0 20px rgba(0,255,80,0.2);
    }
    .category-box.active {
      box-shadow: 0 0 30px rgba(0,255,80,0.35);
    }

    /* No results message */
    #no-results {
      display: none;
      grid-column: 1 / -1;
      text-align: center;
      font-size: 1.5rem;
      opacity: 0.7;
      padding: 4rem 0;
    }
  </style>
</head>
<body>
  ${sharedHeader}

  <!-- 1. HERO -->
  <section id="store-hero">
    <h1>STORE</h1>
    <p>All drops. All edge.</p>
  </section>

  <!-- 2. FEATURED -->
  ${featuredHtml}

  <!-- 3. CATEGORIES -->
  <section id="categories">
    <h2 style="text-align:center; font-size:2.4rem; color:#00ff50; margin-bottom:2rem; text-shadow:0 0 20px #00ff50;">Browse by Category</h2>
    <div style="display:flex; gap:1.2rem; flex-wrap:wrap; justify-content:center; max-width:1400px; margin:0 auto;">
      ${categories.map(cat => `
        <div class="category-box ${cat.id === 'all' ? 'active' : ''}"
             onclick="filterByCategory('${cat.id}', this)">
          <div style="font-size:3rem; margin-bottom:0.8rem;">${cat.svg}</div>
          <div style="font-size:1.35rem; font-weight:700; color:#e0ffe0;">${cat.name}</div>
        </div>
      `).join('')}
    </div>
  </section>

  <!-- 4. ITEMS GRID -->
  <section id="products">
    <div class="grid" id="itemsGrid">
      ${itemsHtml || '<p style="grid-column:1/-1;text-align:center;font-size:1.5rem;opacity:0.7;">No items yet — check back soon!</p>'}
      <p id="no-results">No items in this category yet.</p>
    </div>
  </section>

  <footer>© 2026 LENG — All rights reserved.<br>.</footer>
  ${sharedScripts}

  <script>
    // ─── CAROUSEL ────────────────────────────────────────────────────────────
    const track = document.querySelector('.carousel-track');
    if (track) {
      const slides = document.querySelectorAll('.carousel-slide');
      const prevBtn = document.querySelector('.carousel-prev');
      const nextBtn = document.querySelector('.carousel-next');
      const dots = document.querySelectorAll('.carousel-dot');
      let currentIndex = 0;

      function setPositionByIndex() {
        track.style.transform = \`translateX(\${currentIndex * -100}%)\`;
        dots.forEach((dot, i) => dot.classList.toggle('active', i === currentIndex));
      }

      nextBtn?.addEventListener('click', () => {
        currentIndex = (currentIndex + 1) % slides.length;
        setPositionByIndex();
      });
      prevBtn?.addEventListener('click', () => {
        currentIndex = (currentIndex - 1 + slides.length) % slides.length;
        setPositionByIndex();
      });

      let autoSlide = setInterval(() => {
        currentIndex = (currentIndex + 1) % slides.length;
        setPositionByIndex();
      }, 4800);

      dots.forEach((dot, i) => {
        dot.addEventListener('click', () => {
          currentIndex = i;
          setPositionByIndex();
          clearInterval(autoSlide);
          autoSlide = setInterval(() => {
            currentIndex = (currentIndex + 1) % slides.length;
            setPositionByIndex();
          }, 4800);
        });
      });

      setPositionByIndex();
    }

    // ─── CATEGORY FILTER ─────────────────────────────────────────────────────
    function filterByCategory(cat, clickedEl) {
      // Update active state on category boxes
      document.querySelectorAll('.category-box').forEach(box => box.classList.remove('active'));
      if (clickedEl) clickedEl.classList.add('active');

      const cards = document.querySelectorAll('#itemsGrid .card');
      let visibleCount = 0;

      cards.forEach(card => {
        const show = cat === 'all' || card.dataset.category === cat;
        card.style.display = show ? 'block' : 'none';
        if (show) visibleCount++;
      });

      // Show/hide no-results message
      document.getElementById('no-results').style.display = visibleCount === 0 ? 'block' : 'none';

      // Scroll smoothly to items grid
      document.getElementById('products').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  </script>
</body>
</html>
  `);
});

